import manifest from './icon-manifest.json';

// Generated by scripts/sync_icons.py: the data ids that have a sprite in public/icons.
const IDS: ReadonlySet<string> = new Set(manifest);

/** Sprite url of a game entity by its data id. The only place that knows where icons live. */
export const iconUrl = (id: string): string =>
  `${import.meta.env.BASE_URL}icons/${id}.png`;

/** Generic game icon (public/icons/ui) by its file name with extension (e.g. `calendar.png`). */
export const uiIconUrl = (fileName: string): string =>
  `${import.meta.env.BASE_URL}icons/ui/${fileName}`;

export const hasIcon = (id: string): boolean => IDS.has(id);
